const item = $input.first().json;

// Dados do perfil (vieram do Supabase)
const nome = item.nome_proprietaria || 'proprietária';
const nome_salao = item.nome_salao || 'seu salão';
const telefone = item.telefone || '';
const email = item.email || '';

// Dados do resumo (vieram do FastAPI)
const atendimentos = item.atendimentos ?? 0;
const receita = item.receita_bruta ?? 0;
const gastos_pendentes = item.gastos_pendentes ?? 0;
const saldo = item.saldo_semana ?? 0;
const semana_inicio = item.semana_inicio ?? '';
const semana_fim = item.semana_fim ?? '';

// Formata datas: '2025-05-12' → '12/05'
const fmt = (iso) => {
  if (!iso) return '';
  const [, m, d] = iso.split('-');
  return `${d}/${m}`;
};

// Emoji de saldo
const emoji = saldo > 0 ? '🟢' : saldo === 0 ? '🟡' : '🔴';

// ── Mensagem WhatsApp (markdown do WhatsApp) ───────────────────
const mensagem_whatsapp = [
  `Oi ${nome}! 👋 Aqui está o resumo da semana do *${nome_salao}*.`,
  ``,
  `📅 *Semana ${fmt(semana_inicio)} a ${fmt(semana_fim)}*`,
  ``,
  `🪑 Atendimentos realizados: *${atendimentos}*`,
  `💰 Receita bruta:           *R$ ${receita.toFixed(2).replace('.', ',')}*`,
  `💸 Gastos pendentes:        *R$ ${gastos_pendentes.toFixed(2).replace('.', ',')}*`,
  `${emoji} Saldo da semana:          *R$ ${saldo.toFixed(2).replace('.', ',')}*`,
  ``,
  atendimentos === 0
    ? `Nenhum atendimento registrado essa semana. Não esquece de lançar os atendimentos no app! 📲`
    : gastos_pendentes > 0
      ? `Você tem gastos pendentes essa semana. Acesse o app para marcar como pagos. ✅`
      : `Semana organizada! Continue assim. 💪`,
  ``,
  `_Mensagem automática — App de Gestão do Salão_`
].join('\n');

// ── Mensagem Email (HTML) ──────────────────────────────────────
const cor_saldo = saldo > 0 ? '#3b6d11' : saldo === 0 ? '#854f0b' : '#a32d2d';

const mensagem_email_html = `
<!DOCTYPE html>
<html lang="pt-BR">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="font-family:sans-serif;color:#1a1a1a;max-width:480px;margin:0 auto;padding:24px">
  <p style="margin-bottom:16px">Oi <strong>${nome}</strong> 👋</p>
  <p style="margin-bottom:16px">Aqui está o resumo da semana do <strong>${nome_salao}</strong>.</p>

  <div style="background:#f7f7f5;border-radius:10px;padding:16px;margin-bottom:16px">
    <p style="margin:0 0 12px;font-size:13px;color:#6b6b6b;text-transform:uppercase;letter-spacing:.06em">📅 Semana ${fmt(semana_inicio)} a ${fmt(semana_fim)}</p>
    <table style="width:100%;border-collapse:collapse">
      <tr>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;font-size:14px">🪑 Atendimentos</td>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;text-align:right;font-weight:600">${atendimentos}</td>
      </tr>
      <tr>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;font-size:14px">💰 Receita bruta</td>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;text-align:right;font-weight:600;color:#3b6d11">R$ ${receita.toFixed(2).replace('.', ',')}</td>
      </tr>
      <tr>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;font-size:14px">💸 Gastos pendentes</td>
        <td style="padding:8px 0;border-bottom:1px solid #e5e5e2;text-align:right;font-weight:600;color:#a32d2d">R$ ${gastos_pendentes.toFixed(2).replace('.', ',')}</td>
      </tr>
      <tr style="background:#fff;border-radius:6px">
        <td style="padding:10px 8px;font-size:14px;font-weight:500">📊 Saldo da semana</td>
        <td style="padding:10px 8px;text-align:right;font-size:18px;font-weight:700;color:${cor_saldo}">R$ ${saldo.toFixed(2).replace('.', ',')}</td>
      </tr>
    </table>
  </div>

  <p style="font-size:13px;color:#6b6b6b">
    ${
      atendimentos === 0
        ? 'Nenhum atendimento registrado essa semana. Não se esqueça de lançar os atendimentos no app!'
        : gastos_pendentes > 0
          ? 'Você tem gastos pendentes essa semana. Acesse o app para marcá-los como pagos.'
          : 'Semana organizada! Continue assim. 💪'
    }
  </p>

  <p style="margin-top:32px;font-size:11px;color:#9e9e9e">Mensagem automática — App de Gestão do Salão</p>
</body>
</html>
`;

return [{
  json: {
    user_id: item.user_id,
    nome,
    nome_salao,
    telefone,
    email,
    atendimentos,
    receita,
    gastos_pendentes,
    saldo,
    semana_inicio,
    semana_fim,
    mensagem_whatsapp,
    mensagem_email_html
  }
}];
